      expect(prov?.name, 'my_agent');
      expect(prov?.version, '1.0.0');
      expect(prov?.sha256, matches(RegExp(r'^[0-9a-f]{64}$')));
      expect(prov?.sourceUrl, zip.path);
    });
  });
}
